/* basic layout for site*/
/* Color variables */
.color-white, .banner-wrapper .container .slide-caption, .banner-wrapper.captionbg .container .slide-caption {
  color: #ffffff; }

.color-black {
  color: #000000; }

.color-muted {
  color: rgba(0, 0, 0, 0.5); }

.color-muted-inverse {
  color: rgba(255, 255, 255, 0.5); }

.color-error {
  color: red; }

.color-info {
  color: #0686c8; }

.color-success {
  color: #2ac171; }

.color-gov, .color-theme {
  color: #fbac1b; }

.contrast .color-gov, .contrast .color-theme {
  color: #fff; }

/*--- BACKGROUNDS ---*/
.bg-blue {
  background-color: #0686c8; }

.bg-grey {
  background-color: #c8c8c8; }

.bg-grey-light {
  background-color: #eeeeee; }

.bg-black {
  background-color: #222; }

.bg-white {
  background-color: #ffffff; }

.bg-muted {
  background-color: rgba(0, 0, 0, 0.15); }

.bg-muted-inverse {
  background-color: rgba(255, 255, 255, 0.75); }

.bg-error {
  background-color: red; }

.bg-info {
  background-color: #3f42f6; }

.bg-success {
  background-color: green; }

.bg-gov {
  background-color: #f26522; }

.bg-theme {
  background-color: #fbac1b; }

.bg-theme-light {
  background-color: #fbb534; }

.contrast .bg-blue {
  background-color: #000;
  outline: 1px solid #3b3b3b; }

