.gen-card.nta-card a{
  color: #150202;
}

.gen-card.nta-card > h2 {
  color: #fcf6e8;
  font-size: 1.1em;
  font-weight: 600;
  letter-spacing: 1px;
  padding: 10px 15px;
  text-align: center;
  clip-path: polygon(0% 0%, 100% 0%, 92% 77%, 89% 93%, 85% 100%, 16% 100%, 12% 94%, 9% 79%);
  border-bottom-left-radius: 10px;
  border-bottom-right-radius: 10px;
  width: 190px;
  margin: 0 auto;
  margin-top: -1px;
  margin-bottom: 7px;
  transition: 0.3s ease-in;
}
.gen-card.nta-card .gen-card-content h3 a{
  display: inline-block;
  background-image: linear-gradient(#1d0a69, #1d0a69), linear-gradient(#1d0a69, #1d0a69);
  background-size: 0% 0.1em;
  background-position-y: 100%;
  background-position-x: 0%, 100%;
  background-repeat: no-repeat;
  transition: background-size 0.2s ease-in-out;
  text-decoration: none;
}
.gen-card.nta-card:hover .gen-card-content h3 a,
.gen-card.nta-card .gen-card-content h3 a:focus{
  color: #1d0a69;
  background-size: 100% 0.1em;
}
.gen-card.nta-card .gen-card-img {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 140px;
  height: 140px;
  background: #fff;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.15);
  margin: 22px auto;
  border-radius: 10px;
}
.gen-card.nta-card:hover .gen-card-img {
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.3);
  transform: translateY(-3px);
}
.gen-card.nta-card .gen-card-content{
  padding: 0 15px;
}
.gen-card.nta-card .gen-card-content .genCardContent{
  font-size: 1.15em;
  line-height: 1.5;
}
.gen-card.nta-card .card-activities{
  padding: 0 15px;
  margin-top: 12px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px 25px;
  align-items: center;
  justify-content: center;
}
.gen-card.nta-card .card-activities li{
  list-style-type: none;
  position: relative;
  color: #939393;
  cursor: not-allowed;
  padding: 0;
}
.gen-card.nta-card .card-activities li:after{
  content: "";
  position: absolute;
  right: -20px;
  top: 10px;
  width: 15px;
  height: 1px;
  background: #ccc;
}
.gen-card.nta-card .card-activities li:last-child:after{
  display: none;
}
.gen-card.nta-card .card-activities li a{
  color: #12633C;
  cursor: pointer;
  font-weight: 600;
  background-image: linear-gradient(#12633C, #12633C), linear-gradient(#12633C, #12633C);
  background-size: 0% 0.1em;
  background-position-y: 100%;
  background-position-x: 0%, 100%;
  background-repeat: no-repeat;
  transition: background-size 0.2s ease-in-out;
}
.gen-card.nta-card .card-activities li a:hover{
  background-size: 100% 0.1em;
}
.gen-card.nta-card .card-activities li a:before{
  content: "\f00c";
  font-family: FontAwesome;
}
@media (max-width: 1199px) {
